-- Scontro a squadre (SPEC §5.19, docs/COMBAT.md), stage 5, batch 8: the kits of 15 more Beta and
-- 6 more Alfa characters players own most after the seventh batch
-- (src/lib/combat-kits-batch-8.ts on 25 November 2026, described in docs/COMBAT-KITS.md). Each one
-- was simulated on its own card: with its kit, in a random team against a random team, it wins
-- between 46% and 56%.
--
-- A kit an admin already saved from the EDITOR for one of these characters stays as it is.

insert into public.combat_kits (definition_id, kit)
select d.id, k.kit::jsonb
from (values
