join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P054', 'P075', 'P171', 'P207', 'P208', 'P226', 'P056', 'P172', 'P210', 'P228', 'P076', 'P174', 'P225', 'P089', 'P102', 'P103', 'P120', 'P140', 'P178', 'P091', 'P121')) <> 21 then
    raise exception 'a character of the eighth batch has no kit';
  end if;
end $$;
